namespace {
struct TempRoot {fs::path path;TempRoot(){static unsigned n=0;path=fs::temp_directory_path()/("MapleRGL_challenge_test_"+std::to_string(std::chrono::steady_clock::now().time_since_epoch().count())+"_"+std::to_string(++n));assert(fs::create_directory(path));}~TempRoot(){std::error_code ec;auto parent=fs::temp_directory_path(ec).lexically_normal();auto target=path.lexically_normal();if(!ec&&target.parent_path()==parent&&target.filename().u8string().find("MapleRGL_challenge_test_")==0)fs::remove_all(target,ec);}};
std::string bytes(const fs::path& p){std::ifstream f(p,std::ios::binary);return {std::istreambuf_iterator<char>(f),{}};}
void write(const fs::path& p,const std::string& s){std::ofstream f(p,std::ios::binary|std::ios::trunc);assert(f);f<<s;f.close();assert(!f.fail());}
bool close_to(double a,double b){return std::abs(a-b)<.001;}
void fixed_day_fairness_and_invalid_dates(){
 TempRoot fresh,strong;json experienced;{ProgressionStore seed(strong.path);assert(seed.save_settings({}));experienced=json::parse(bytes(seed.profile_path()));}experienced["crystals"]=9000;for(const auto& d:talent_definitions())experienced["talents"][d.key]=d.max_rank;for(int i=1;i<equipment_count;++i)experienced["owned_equipment"][i]=true;experienced["equipped"]={int(EquipmentId::ReedBow),int(EquipmentId::ScholarRobe),int(EquipmentId::AmberPendant)};experienced["unlocked_relic_mask"]=(1u<<relic_count)-1;write(strong.path/"profile.json",experienced.dump());
 ProgressionStore a(fresh.path),b(strong.path);assert(b.run_bonuses().damage_bonus>0);const std::string date="2026-11-11";auto spec=make_daily_spec(date);assert(spec.valid&&spec.seed==42515751u&&spec.setup.daily_key==20261111u&&spec.setup.mode==RunMode::Daily&&spec.setup.difficulty==Difficulty::Normal&&!spec.rules.empty());assert(make_daily_spec(date).seed==spec.seed&&make_daily_spec("2026-11-12").seed!=spec.seed);
 auto absent=bytes(a.profile_path());for(const std::string bad:{"","2026-2-01","2026-02-29","2024-02-30","2026-13-01","0000-01-01","2026-11-11extra"})assert(!make_daily_spec(bad).valid&&!a.begin_daily(bad)&&bytes(a.profile_path())==absent);assert(make_daily_spec("2024-02-29").valid);
 assert(a.mode_unlocked(RunMode::Endless)&&a.mode_unlocked(RunMode::Daily)&&!a.difficulty_unlocked(Difficulty::Hard)&&!a.difficulty_unlocked(Difficulty::Nightmare));assert(!a.begin_run(CharacterClass::Archer,1,RunMode::Classic,Difficulty::Hard)&&!a.begin_run(CharacterClass::Archer,1,RunMode::Daily)&&bytes(a.profile_path())==absent);
 assert(a.begin_daily(date)&&b.begin_daily(date));const auto& x=*a.profile().active_run;const auto& y=*b.profile().active_run;assert(x.character==y.character&&x.seed==y.seed&&x.daily_date==date&&x.setup.equipment==y.setup.equipment&&x.setup.unlocked_relic_mask==y.setup.unlocked_relic_mask&&x.setup.starting_relic_mask==y.setup.starting_relic_mask&&x.setup.daily_variant==y.setup.daily_variant);assert(x.bonuses.damage_bonus==0&&y.bonuses.damage_bonus==0&&x.bonuses.health_bonus==0&&y.bonuses.upgrade_rerolls==0);
 Game ga,gb;ga.start(x.character,x.seed,x.bonuses,x.setup);gb.start(CharacterClass::Warrior,y.seed,b.run_bonuses(),y.setup);assert(ga.character==gb.character&&ga.character==spec.character&&gb.run_bonuses().damage_bonus==0&&close_to(ga.player.max_hp,gb.player.max_hp)&&close_to(ga.damage_multiplier,gb.damage_multiplier)&&ga.owned_relic_mask()==gb.owned_relic_mask());
}
RunReport daily_report(const ActiveRun& active,int kills,int level,float elapsed,double damage){
 Game g;g.start(active.character,active.seed,active.bonuses,active.setup);g.enemies.clear();Enemy ranger;ranger.id=700;ranger.kind=EnemyKind::Ranger;ranger.pos={50,0};ranger.hp=ranger.max_hp=10000;ranger.speed=0;ranger.damage=0;g.enemies.push_back(ranger);g.update(.01f);assert(g.metrics.enemy_seen_mask&(1u<<int(EnemyKind::Ranger)));
 g.elapsed=elapsed;g.kills=kills;g.player.level=level;g.metrics.enemy_kills_by_kind.fill(0);g.metrics.enemy_kills_by_kind[int(EnemyKind::Slime)]=kills;g.metrics.skill_damage.fill(0);g.metrics.skill_damage[0]=damage;return make_run_report(g,RunOutcome::Victory,active.seed);
}
void daily_best_and_reward_once(){
 TempRoot t;const std::string day="2026-11-11";uint64_t first_id=0;int64_t total=0;uint64_t best_score=0;CharacterClass character;RunReport first;
 {
  ProgressionStore store(t.path);auto begin=store.begin_daily(day);assert(begin);first_id=begin.run_id;character=store.profile().active_run->character;first=daily_report(*store.profile().active_run,100,10,600,10000);assert(settlement_crystals(first)==0);auto finish=store.settle(first_id,first);assert(finish&&finish.progress_crystals_awarded==0&&finish.daily_crystals_awarded==8&&finish.crystals_awarded==8+finish.achievement_crystals_awarded);total=store.profile().crystals;
  auto record=store.daily_record(day);assert(record&&record->attempts==1&&record->wins==1&&record->reward_claimed&&record->best.kills==100&&record->best.level==10&&record->best.damage>=10000);best_score=record->best.best_score;auto best=store.run_best(character,Difficulty::Normal,RunMode::Daily);assert(best.recorded&&best.runs==1&&best.victories==1&&best.kills==100);assert(store.bestiary()[int(EnemyKind::Ranger)].seen&&store.bestiary()[int(EnemyKind::Ranger)].kills==0);assert(store.bestiary()[int(EnemyKind::Slime)].kills==100);
  auto saved=bytes(store.profile_path());assert(store.settle(first_id,first).already_claimed&&bytes(store.profile_path())==saved);assert(close_to(store.profile().records.total_elapsed,600)&&store.profile().records.class_runs[int(character)]==1);
  auto again=store.begin_daily(day);assert(again);auto lower=daily_report(*store.profile().active_run,20,2,100,50);auto repeat=store.settle(again.run_id,lower);assert(repeat&&repeat.daily_crystals_awarded==0&&repeat.progress_crystals_awarded==0&&repeat.achievement_crystals_awarded==0&&store.profile().crystals==total);record=store.daily_record(day);assert(record->attempts==2&&record->wins==2&&record->best.best_score==best_score&&record->best.kills==100&&record->best.level==10&&record->best.damage>=10000&&close_to(record->best.longest,600));assert(close_to(store.profile().records.total_elapsed,700)&&store.profile().records.class_runs[int(character)]==2);
 }
 ProgressionStore restarted(t.path);assert(restarted.daily_record(day)->reward_claimed&&restarted.settle(first_id,first).already_claimed&&restarted.profile().crystals==total);auto next=restarted.begin_daily("2026-11-12");assert(next);auto next_report=daily_report(*restarted.profile().active_run,20,2,600,100);auto next_day=restarted.settle(next.run_id,next_report);assert(next_day&&next_day.daily_crystals_awarded==8&&!restarted.difficulty_unlocked(Difficulty::Hard)&&!restarted.difficulty_unlocked(Difficulty::Nightmare));
}
void finish_chapter(Game& g){int n=g.chapter_index()+1;g.elapsed=600;g.kills=100*n;g.metrics.enemy_kills_by_kind.fill(0);g.metrics.enemy_kills_by_kind[0]=g.kills;g.metrics.chapters_cleared=n;g.metrics.enemy_seen_mask|=1u;g.state=n==3?State::Victory:State::ChapterComplete;}
void difficulty_unlocks_and_mode_records(){
 TempRoot t;ProgressionStore p(t.path);assert(!p.difficulty_unlocked(Difficulty::Hard));auto run=p.begin_run(CharacterClass::Archer,11,RunMode::Campaign);assert(run);Game game;game.start(CharacterClass::Archer,11,p.profile().active_run->bonuses,p.profile().active_run->setup);
 for(int chapter=0;chapter<2;++chapter){finish_chapter(game);RunBuild b;assert(game.export_build(b)&&p.claim_chapter(run.run_id,chapter,make_run_report(game,RunOutcome::Victory,11),b));assert(!p.difficulty_unlocked(Difficulty::Hard));assert(p.choose_chapter_supply(run.run_id,2)&&p.checkpoint_build(b)&&game.restore_build(b)&&game.advance_chapter());}
 finish_chapter(game);assert(p.settle(run.run_id,make_run_report(game,RunOutcome::Victory,11))&&p.difficulty_unlocked(Difficulty::Hard)&&!p.difficulty_unlocked(Difficulty::Nightmare));
 auto hard=p.begin_run(CharacterClass::Mage,12,RunMode::Classic,Difficulty::Hard);assert(hard);Config quiet;quiet.duration=.2f;quiet.boss_time=quiet.elite_interval=quiet.first_event_time=1e6f;quiet.max_enemies=0;Game challenge(quiet);challenge.start(CharacterClass::Mage,12,p.profile().active_run->bonuses,p.profile().active_run->setup);for(int i=0;i<100&&challenge.state==State::Playing;++i)challenge.update(.01f);assert(challenge.state==State::Victory);auto report=make_run_report(challenge,RunOutcome::Victory,12);assert(report.difficulty==Difficulty::Hard&&p.settle(hard.run_id,report)&&p.difficulty_unlocked(Difficulty::Nightmare));assert(p.run_best(CharacterClass::Mage,Difficulty::Hard,RunMode::Classic).victories==1);
 auto endless=p.begin_run(CharacterClass::Warrior,13,RunMode::Endless,Difficulty::Nightmare);assert(endless);Game long_run;long_run.start(CharacterClass::Warrior,13,p.profile().active_run->bonuses,p.profile().active_run->setup);long_run.elapsed=4500;long_run.kills=1000;long_run.metrics.bosses_defeated=7;long_run.metrics.enemy_kills_by_kind[int(EnemyKind::Boss)]=7;long_run.metrics.enemy_kills_by_kind[0]=993;long_run.metrics.endless_cycle=7;auto long_report=make_run_report(long_run,RunOutcome::Defeat,13);assert(p.settle(endless.run_id,long_report));auto best=p.run_best(CharacterClass::Warrior,Difficulty::Nightmare,RunMode::Endless);assert(best.recorded&&best.bosses==7&&close_to(best.longest,4500)&&best.kills==1000);
}
void schema_three_boundary_migration(){
 TempRoot t;json old;
 {ProgressionStore p(t.path);auto run=p.begin_run(CharacterClass::Archer,3,RunMode::Campaign);assert(run);Game g;g.start(CharacterClass::Archer,3,p.profile().active_run->bonuses,p.profile().active_run->setup);finish_chapter(g);g.player.xp=7;g.metrics.xp_acquired=7;g.metrics.xp_by_minute[5]=7;RunBuild b;assert(g.export_build(b)&&p.claim_chapter(run.run_id,0,make_run_report(g,RunOutcome::Victory,3),b));old=json::parse(bytes(p.profile_path()));}
 old["schema_version"]=3;for(const char* key:{"nightmare_eligible","enemy_seen_mask","bests","daily_records"})old.erase(key);old["records"].erase("total_elapsed");old["records"].erase("class_runs");old["active_run"].erase("daily_date");
 for(const char* key:{"difficulty","daily_key","daily_variant","daily_character","starting_relic_mask"}){old["active_run"]["setup"].erase(key);old["chapter_checkpoint"]["build"].erase(key);}for(const char* report:{"claimed_report","accounted_report"})for(const char* key:{"difficulty","daily_key","daily_variant","enemy_seen_mask","endless_cycle"})old["active_run"][report].erase(key);auto& metrics=old["chapter_checkpoint"]["build"]["metrics"];metrics.erase("enemy_seen_mask");metrics.erase("endless_cycle");metrics["xp_by_minute"]=std::vector<double>(10,0);metrics["xp_by_minute"][5]=7;write(t.path/"profile.json",old.dump());
 ProgressionStore migrated(t.path);assert(!migrated.read_only()&&migrated.load_state()==ProfileLoadState::Migrated);RunBuild b;assert(migrated.checkpoint_build(b)&&b.difficulty==Difficulty::Normal&&b.metrics.xp_by_minute.size()==60&&b.metrics.xp_by_minute[5]==7);for(size_t i=10;i<b.metrics.xp_by_minute.size();++i)assert(b.metrics.xp_by_minute[i]==0);assert(migrated.save_settings(migrated.profile().settings)&&json::parse(bytes(migrated.profile_path()))["schema_version"]==profile_schema_version);
}
}
int main(){fixed_day_fairness_and_invalid_dates();daily_best_and_reward_once();difficulty_unlocks_and_mode_records();schema_three_boundary_migration();std::cout<<"challenge_progression: fixed-date fairness, once-daily rewards, monotonic local bests, actual difficulty unlocks, mode records, seen-without-kill bestiary and schema-3 checkpoint migration passed (isolated roots only)\n";}
